CREATE VIEW read_character_resources AS SELECT n.id,(SELECT json_group_object(f.key,json(CASE f.key WHEN 'hp' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.hp END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.hp END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.hp END) END WHEN 'temp' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.temp_hp END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.temp_hp END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.temp_hp END) END WHEN 'will' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.will END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.will END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.will END) END WHEN 'general' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.general END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.general END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.general END) END WHEN 'inventory' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.inventory END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.inventory END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.inventory END) END WHEN 'wounds' THEN CASE WHEN f.value='array' THEN (SELECT json_group_array(json(v)) FROM (SELECT CASE value_type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN amount WHEN 'array' THEN amount ELSE json_quote(amount) END AS v FROM character_wounds WHERE character_id=n.id ORDER BY ordinal)) ELSE CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN json_extract(n.extras_json,'$."wounds"') WHEN 'array' THEN json_extract(n.extras_json,'$."wounds"') ELSE json_quote(json_extract(n.extras_json,'$."wounds"')) END END ELSE (SELECT CASE type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN value WHEN 'array' THEN value ELSE json_quote(value) END FROM json_each(n.extras_json) WHERE key=f.key) END)) FROM json_each(n.shape_json) f) AS document FROM character_resources n;

