array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.summary END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.summary END) END WHEN 'Faction' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.faction END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.faction END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.faction END) END WHEN 'Speed' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.speed END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.speed END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.speed END) END WHEN 'Class Desc' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.description END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.description END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.description END) END WHEN 'Level 1 Perk' THEN (SELECT CASE value_type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN description WHEN 'array' THEN description ELSE json_quote(description) END FROM class_perks WHERE class_id=n.id AND level=1) WHEN 'Level 2 Perk' THEN (SELECT CASE value_type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN description WHEN 'array' THEN description ELSE json_quote(description) END FROM class_perks WHERE class_id=n.id AND level=2) WHEN 'Level 3 Perk' THEN (SELECT CASE value_type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN description WHEN 'array' THEN description ELSE json_quote(description) END FROM class_perks WHERE class_id=n.id AND level=3) WHEN 'Level 4 Perk' THEN (SELECT CASE value_type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN description WHEN 'array' THEN description ELSE json_quote(description) END FROM class_perks WHERE class_id=n.id AND level=4) WHEN 'Level 5 Perk' THEN (SELECT CASE value_type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN description WHEN 'array' THEN description ELSE json_quote(description) END FROM class_perks WHERE class_id=n.id AND level=5) WHEN 'Level 6 Perk' THEN (SELECT CASE value_type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN description WHEN 'array' THEN description ELSE json_quote(description) END FROM class_perks WHERE class_id=n.id AND level=6) WHEN 'Level 7 Perk' THEN (SELECT CASE value_type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN description WHEN 'array' THEN description ELSE json_quote(description) END FROM class_perks WHERE class_id=n.id AND level=7) WHEN 'Level 8 Perk' THEN (SELECT CASE value_type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN description WHEN 'array' THEN description ELSE json_quote(description) END FROM class_perks WHERE class_id=n.id AND level=8) ELSE (SELECT CASE type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN value WHEN 'array' THEN value ELSE json_quote(value) END FROM json_each(n.extras_json) WHERE key=f.key) END)) FROM json_each(n.shape_json) f) AS document FROM catalog_classes n;

