EN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.quote END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.quote END) END WHEN 'Desc' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.description END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.description END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.description END) END WHEN 'Enable' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.enabled END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.enabled END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.enabled END) END WHEN 'Belief Effect 1' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.effect_1 END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.effect_1 END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.effect_1 END) END WHEN 'Belief Effect 2' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.effect_2 END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.effect_2 END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.effect_2 END) END  ELSE (SELECT CASE type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN value WHEN 'array' THEN value ELSE json_quote(value) END FROM json_each(n.extras_json) WHERE key=f.key) END)) FROM json_each(n.shape_json) f) AS document FROM catalog_beliefs n;

