ASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.personality END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.personality END) END WHEN 'Desc' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.description END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.description END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.description END) END WHEN 'Skill 1' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.skill_1 END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.skill_1 END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.skill_1 END) END WHEN 'Skill 2' THEN CASE f.value WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.skill_2 END WHEN 'array' THEN CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.skill_2 END ELSE json_quote(CASE WHEN f.value IN('object','array') THEN (SELECT value FROM json_each(n.extras_json) WHERE key=f.key) ELSE n.skill_2 END) END  ELSE (SELECT CASE type WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' WHEN 'null' THEN 'null' WHEN 'object' THEN value WHEN 'array' THEN value ELSE json_quote(value) END FROM json_each(n.extras_json) WHERE key=f.key) END)) FROM json_each(n.shape_json) f) AS document FROM catalog_backgrounds n;

CREATE VIEW normalized_characters AS SELECT c.id,c.campaign_id,c.owner_email,c.owner_user_id,p.document AS sheet,r.document AS state,c.version,c.edit_class,c.edit_spells FROM characters c JOIN read_character_profiles p ON p.id=c.id JOIN read_character_resources r ON r.id=c.id;

CREATE VIEW normalized_definitions_level_0_part_1 AS SELECT * FROM (SELECT d.kind,d.id,n.document AS payload,d.version,d.archived FROM definitions d JOIN read_catalog_classes n ON n.id=d.id WHERE d.kind='class' UNION ALL SELECT d.kind,d.id,n.document AS payload,d.version,d.archived FROM definitions d JOIN read_catalog_schools n ON n.id=d.id WHERE d.kind='school' UNION ALL SELECT d.kind,d.id,n.document AS payload,d.version,d.archived FROM definitions d JOIN read_catalog_spells n ON n.id=d.id WHERE d.kind='spell' UNION ALL SELECT d.kind,d.id,n.document AS payload,d.version,d.archived FROM definitions d JOIN read_catalog_weapons n ON n.id=d.id WHERE d.kind='weapon') LIMIT -1 OFFSET 0;

CREATE VIEW normalized_definitions_level_0_part_2 AS SELECT * FROM (SELECT d.kind,d.id,n.document AS payload,d.version,d.archived FROM definitions d JOIN read_catalog_beliefs n ON n.id=d.id WHERE d.kind='beliefs' UNION ALL SELECT d.kind,d.id,n.document AS payload,d.version,d.archived FROM definitions d JOIN read_catalog_backgrounds n ON n.id=d.id WHERE d.kind='background' UNION ALL SELECT * FROM definitions WHERE kind NOT IN('class','school','spell','weapon','beliefs','background')) LIMIT -1 OFFSET 0;

CREATE VIEW normalized_definitions AS SELECT * FROM (SELECT * FROM normalized_definitions_level_0_part_1 UNION ALL SELECT * FROM normalized_definitions_level_0_part_2) LIMIT -1 OFFSET 0;

CREATE VIEW project_character_beliefs AS WITH RECURSIVE parts(character_id,ordinal,rest,belief_id) AS (SELECT id,-1,CAST(COALESCE(beliefs,'') AS TEXT)||',','' FROM character_profiles UNION ALL SELECT character_id,ordinal+1,substr(rest,instr(rest,',')+1),trim(substr(rest,1,instr(rest,',')-1),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)) FROM parts WHERE rest<>'') SELECT character_id,ordinal,belief_id FROM parts WHERE belief_id<>'';
CREATE TABLE character_beliefs(character_id TEXT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,belief_id TEXT NOT NULL,PRIMARY KEY(character_id,ordinal));
INSERT INTO character_beliefs SELECT * FROM project_character_beliefs;

CREATE VIEW normalization_references_level_0_part_1 AS SELECT * FROM (SELECT 'character' AS source_kind,id AS source_id,'Class' AS field,0 AS ordinal,'class' AS target_kind,class_id AS target_id FROM character_profiles UNION ALL SELECT 'character',id,'School',0,'school',school_id FROM character_profiles UNION ALL SELECT 'character',id,'Background',0,'background',background_id FROM character_profiles UNION ALL SELECT 'character',character_id,'Beliefs',ordinal,'beliefs',belief_id FROM character_beliefs) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_references_level_0_part_2 AS SELECT * FROM (SELECT 'character',character_id,'Spells',0,'spell',spell_id FROM character_spells UNION ALL SELECT 'character',character_id,'Weapons',0,'weapon',weapon_id FROM character_weapons UNION ALL SELECT 'school',id,'Class',0,'class',class_id FROM catalog_schools UNION ALL SELECT 'school',id,'Belief',0,'beliefs',belief_id FROM catalog_schools) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_references_level_0_part_3 AS SELECT * FROM (SELECT 'school',id,'Main Spell',0,'spell',main_spell_id FROM catalog_schools UNION ALL SELECT 'spell',id,'School',0,'school',school_id FROM catalog_spells) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_references AS SELECT * FROM (SELECT * FROM normalization_references_level_0_part_1 UNION ALL SELECT * FROM normalization_references_level_0_part_2 UNION ALL SELECT * FROM normalization_references_level_0_part_3) LIMIT -1 OFFSET 0;

CREATE TABLE definition_links(source_kind TEXT NOT NULL,source_id TEXT NOT NULL,field TEXT NOT NULL,ordinal INTEGER NOT NULL,target_kind TEXT NOT NULL,target_id TEXT NOT NULL,PRIMARY KEY(source_kind,source_id,field,ordinal,target_kind,target_id),FOREIGN KEY(target_kind,target_id) REFERENCES definitions(kind,id));
INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>'';

CREATE TRIGGER normalize_characters_insert AFTER INSERT ON characters BEGIN
SELECT CASE WHEN json_valid(NEW.sheet) AND json_type(NEW.sheet)='object' THEN 1 ELSE RAISE(ABORT,'normalization: invalid JSON object') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM json_each(NEW.sheet) GROUP BY key HAVING COUNT(*)>1) THEN 1 ELSE RAISE(ABORT,'normalization: duplicate JSON key') END;
SELECT CASE WHEN json_valid(NEW.state) AND json_type(NEW.state)='object' THEN 1 ELSE RAISE(ABORT,'normalization: invalid JSON object') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM json_each(NEW.state) GROUP BY key HAVING COUNT(*)>1) THEN 1 ELSE RAISE(ABORT,'normalization: duplicate JSON key') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM json_each(NEW.sheet,'$."_baseStats"') WHERE json_type(NEW.sheet,'$."_baseStats"')='object' GROUP BY key HAVING COUNT(*)>1) THEN 1 ELSE RAISE(ABORT,'normalization: duplicate allocation key') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM json_each(NEW.sheet,'$."_growth"') WHERE json_type(NEW.sheet,'$."_growth"')='object' GROUP BY key HAVING COUNT(*)>1) THEN 1 ELSE RAISE(ABORT,'normalization: duplicate allocation key') END;
DELETE FROM character_profiles WHERE id=NEW.id;
INSERT INTO character_profiles(id,source_id,source_campaign,name,level,class_id,school_id,background_id,beliefs,story,strength,dexterity,constitution,intelligence,wisdom,charisma,max_hp,max_will,armor_class,spell_dc,spell_slots,source_spells,source_weapons,source_inventory,source_notes,source_hp,source_will,shape_json,extras_json) SELECT * FROM project_character_profiles WHERE id=NEW.id;
DELETE FROM character_base_stats WHERE id=NEW.id;
INSERT INTO character_base_stats(id,strength,dexterity,constitution,intelligence,wisdom,charisma,shape_json,extras_json) SELECT * FROM project_character_base_stats WHERE id=NEW.id;
DELETE FROM character_growth WHERE id=NEW.id;
INSERT INTO character_growth(id,strength,dexterity,constitution,intelligence,wisdom,charisma,shape_json,extras_json) SELECT * FROM project_character_growth WHERE id=NEW.id;
DELETE FROM character_resources WHERE id=NEW.id;
INSERT INTO character_resources(id,hp,temp_hp,will,general,inventory,shape_json,extras_json) SELECT * FROM project_character_resources WHERE id=NEW.id;
DELETE FROM character_wounds WHERE character_id=NEW.id; INSERT INTO character_wounds SELECT NEW.id,CAST(key AS INTEGER),value,type FROM json_each(NEW.state,'$.wounds') WHERE json_type(NEW.state,'$.wounds')='array'; DELETE FROM character_beliefs WHERE character_id=NEW.id; INSERT INTO character_beliefs SELECT * FROM project_character_beliefs WHERE character_id=NEW.id;
DELETE FROM definition_links WHERE source_kind='character' AND source_id=NEW.id; INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE (source_kind='character' AND source_id=NEW.id) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>'';
END;

