INSERT INTO catalog_weapons(id,source_id,name,weapon_type,damage,effect,reveal_effect,available,shape_json,extras_json) SELECT * FROM project_catalog_weapons WHERE id=NEW.id AND NEW.kind='weapon';
DELETE FROM catalog_beliefs WHERE id=NEW.id AND NEW.kind='beliefs';
INSERT INTO catalog_beliefs(id,source_id,name,title,quote,description,enabled,effect_1,effect_2,shape_json,extras_json) SELECT * FROM project_catalog_beliefs WHERE id=NEW.id AND NEW.kind='beliefs';
DELETE FROM catalog_backgrounds WHERE id=NEW.id AND NEW.kind='background';
INSERT INTO catalog_backgrounds(id,source_id,name,main_branch,personality,description,skill_1,skill_2,shape_json,extras_json) SELECT * FROM project_catalog_backgrounds WHERE id=NEW.id AND NEW.kind='background';
INSERT INTO class_perks SELECT NEW.id,CAST(substr(key,7,1) AS INTEGER),value,type FROM json_each(NEW.payload) WHERE NEW.kind='class' AND key IN('Level 1 Perk','Level 2 Perk','Level 3 Perk','Level 4 Perk','Level 5 Perk','Level 6 Perk','Level 7 Perk','Level 8 Perk');
DELETE FROM definition_links WHERE (source_kind=NEW.kind AND source_id=NEW.id) OR (target_kind=NEW.kind AND target_id=NEW.id); INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE ((source_kind=NEW.kind AND source_id=NEW.id) OR (target_kind=NEW.kind AND target_id=NEW.id)) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>'';
END;

CREATE TRIGGER normalize_character_spells_insert AFTER INSERT ON character_spells BEGIN DELETE FROM definition_links WHERE source_kind='character' AND source_id=NEW.character_id; INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE (source_kind='character' AND source_id=NEW.character_id) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>'';  END;

CREATE TRIGGER normalize_character_spells_update AFTER UPDATE ON character_spells BEGIN DELETE FROM definition_links WHERE source_kind='character' AND source_id=NEW.character_id; INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE (source_kind='character' AND source_id=NEW.character_id) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>''; DELETE FROM definition_links WHERE source_kind='character' AND source_id=OLD.character_id; INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE (source_kind='character' AND source_id=OLD.character_id) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>''; END;

CREATE TRIGGER normalize_character_spells_delete AFTER DELETE ON character_spells BEGIN DELETE FROM definition_links WHERE source_kind='character' AND source_id=OLD.character_id; INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE (source_kind='character' AND source_id=OLD.character_id) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>'';  END;

CREATE TRIGGER normalize_character_weapons_insert AFTER INSERT ON character_weapons BEGIN DELETE FROM definition_links WHERE source_kind='character' AND source_id=NEW.character_id; INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE (source_kind='character' AND source_id=NEW.character_id) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>'';  END;

CREATE TRIGGER normalize_character_weapons_update AFTER UPDATE ON character_weapons BEGIN DELETE FROM definition_links WHERE source_kind='character' AND source_id=NEW.character_id; INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE (source_kind='character' AND source_id=NEW.character_id) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>''; DELETE FROM definition_links WHERE source_kind='character' AND source_id=OLD.character_id; INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE (source_kind='character' AND source_id=OLD.character_id) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>''; END;

CREATE TRIGGER normalize_character_weapons_delete AFTER DELETE ON character_weapons BEGIN DELETE FROM definition_links WHERE source_kind='character' AND source_id=OLD.character_id; INSERT INTO definition_links SELECT r.* FROM normalization_references r JOIN definitions d ON d.kind=r.target_kind AND d.id=r.target_id WHERE (source_kind='character' AND source_id=OLD.character_id) AND r.source_id IS NOT NULL AND r.target_id IS NOT NULL AND r.target_id<>'';  END;

CREATE TRIGGER normalize_characters_before_delete BEFORE DELETE ON characters BEGIN DELETE FROM definition_links WHERE source_kind='character' AND source_id=OLD.id; END;

CREATE TRIGGER normalize_definitions_before_delete BEFORE DELETE ON definitions BEGIN DELETE FROM definition_links WHERE (source_kind=OLD.kind AND source_id=OLD.id) OR (target_kind=OLD.kind AND target_id=OLD.id); END;

CREATE INDEX character_profiles_source_id ON character_profiles(source_id);

CREATE INDEX character_profiles_class_id ON character_profiles(class_id);

CREATE INDEX character_profiles_school_id ON character_profiles(school_id);

CREATE INDEX character_profiles_background_id ON character_profiles(background_id);

CREATE INDEX catalog_classes_source_id ON catalog_classes(source_id);

CREATE INDEX catalog_schools_source_id ON catalog_schools(source_id);

CREATE INDEX catalog_schools_class_id ON catalog_schools(class_id);

CREATE INDEX catalog_schools_belief_id ON catalog_schools(belief_id);

CREATE INDEX catalog_schools_main_spell_id ON catalog_schools(main_spell_id);

CREATE INDEX catalog_spells_source_id ON catalog_spells(source_id);

CREATE INDEX catalog_spells_school_id ON catalog_spells(school_id);

CREATE INDEX catalog_weapons_source_id ON catalog_weapons(source_id);

CREATE INDEX catalog_beliefs_source_id ON catalog_beliefs(source_id);

CREATE INDEX catalog_backgrounds_source_id ON catalog_backgrounds(source_id);

CREATE INDEX character_beliefs_target ON character_beliefs(belief_id); CREATE INDEX definition_links_target ON definition_links(target_kind,target_id);

CREATE VIEW normalization_issues_level_0_part_1 AS SELECT * FROM (SELECT 'character' AS entity,n.id,'sheet' AS scope,e.key AS field,CASE WHEN e.key IN('system_id','Campaign','Character Name','Level','Class','School','Background','Beliefs','Background Story','Strength','Dexterity','Constitution','Intelligence','Wisdom','Charisma','Max Health','Max Willpower','Armor Class','Spell Difficulty','Available Spell Slots','Spells','Weapons','Inventory','Notes','Current Health','Current Willpower','_baseStats','_growth') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM character_profiles n,json_each(n.extras_json) e UNION ALL SELECT 'character',id,'sheet','Character Name','missing_field' FROM character_profiles WHERE json_type(shape_json,'$."Character Name"') IS NULL UNION ALL SELECT 'character',id,'sheet','Level','missing_field' FROM character_profiles WHERE json_type(shape_json,'$."Level"') IS NULL UNION ALL SELECT 'character',id,'sheet','Class','missing_field' FROM character_profiles WHERE json_type(shape_json,'$."Class"') IS NULL) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_2 AS SELECT * FROM (SELECT 'character',id,'sheet','School','missing_field' FROM character_profiles WHERE json_type(shape_json,'$."School"') IS NULL UNION ALL SELECT 'character',id,'sheet','system_id','id_mismatch' FROM character_profiles WHERE source_id IS NOT NULL AND source_id<>id UNION ALL SELECT 'character' AS entity,n.id,'_baseStats' AS scope,e.key AS field,CASE WHEN e.key IN('Strength','Dexterity','Constitution','Intelligence','Wisdom','Charisma') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM character_base_stats n,json_each(n.extras_json) e UNION ALL SELECT 'character' AS entity,n.id,'_growth' AS scope,e.key AS field,CASE WHEN e.key IN('Strength','Dexterity','Constitution','Intelligence','Wisdom','Charisma') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM character_growth n,json_each(n.extras_json) e) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_3 AS SELECT * FROM (SELECT 'character' AS entity,n.id,'state' AS scope,e.key AS field,CASE WHEN e.key IN('hp','temp','will','general','inventory','wounds') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM character_resources n,json_each(n.extras_json) e UNION ALL SELECT 'character',id,'state','hp','missing_field' FROM character_resources WHERE json_type(shape_json,'$."hp"') IS NULL UNION ALL SELECT 'character',id,'state','temp','missing_field' FROM character_resources WHERE json_type(shape_json,'$."temp"') IS NULL UNION ALL SELECT 'character',id,'state','will','missing_field' FROM character_resources WHERE json_type(shape_json,'$."will"') IS NULL) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_4 AS SELECT * FROM (SELECT 'character',id,'state','wounds','missing_field' FROM character_resources WHERE json_type(shape_json,'$."wounds"') IS NULL UNION ALL SELECT 'class' AS entity,n.id,'payload' AS scope,e.key AS field,CASE WHEN e.key IN('system_id','Class Name (Chinese)','Class Name (English)','Short Desc','Faction','Speed','Class Desc','Level 1 Perk','Level 2 Perk','Level 3 Perk','Level 4 Perk','Level 5 Perk','Level 6 Perk','Level 7 Perk','Level 8 Perk') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM catalog_classes n,json_each(n.extras_json) e UNION ALL SELECT 'class',id,'payload','system_id','missing_field' FROM catalog_classes WHERE json_type(shape_json,'$."system_id"') IS NULL UNION ALL SELECT 'class',id,'payload','Class Name (Chinese)','missing_field' FROM catalog_classes WHERE json_type(shape_json,'$."Class Name (Chinese)"') IS NULL) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_5 AS SELECT * FROM (SELECT 'class',id,'payload','system_id','id_mismatch' FROM catalog_classes WHERE source_id IS NOT NULL AND source_id<>id UNION ALL SELECT 'school' AS entity,n.id,'payload' AS scope,e.key AS field,CASE WHEN e.key IN('system_id','School Name (Chinese)','School Name (English)','Class','Belief','Main Spell','Title','Passive','Desc') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM catalog_schools n,json_each(n.extras_json) e UNION ALL SELECT 'school',id,'payload','system_id','missing_field' FROM catalog_schools WHERE json_type(shape_json,'$."system_id"') IS NULL UNION ALL SELECT 'school',id,'payload','School Name (Chinese)','missing_field' FROM catalog_schools WHERE json_type(shape_json,'$."School Name (Chinese)"') IS NULL) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_6 AS SELECT * FROM (SELECT 'school',id,'payload','system_id','id_mismatch' FROM catalog_schools WHERE source_id IS NOT NULL AND source_id<>id UNION ALL SELECT 'spell' AS entity,n.id,'payload' AS scope,e.key AS field,CASE WHEN e.key IN('system_id','Spell Name (Chinese)','Spell Name (English)','School','Action Type','Target','Exclusive','Spell Desc') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM catalog_spells n,json_each(n.extras_json) e UNION ALL SELECT 'spell',id,'payload','system_id','missing_field' FROM catalog_spells WHERE json_type(shape_json,'$."system_id"') IS NULL UNION ALL SELECT 'spell',id,'payload','Spell Name (Chinese)','missing_field' FROM catalog_spells WHERE json_type(shape_json,'$."Spell Name (Chinese)"') IS NULL) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_7 AS SELECT * FROM (SELECT 'spell',id,'payload','system_id','id_mismatch' FROM catalog_spells WHERE source_id IS NOT NULL AND source_id<>id UNION ALL SELECT 'weapon' AS entity,n.id,'payload' AS scope,e.key AS field,CASE WHEN e.key IN('system_id','Weapon Name','Weapon Type','Damage','Effect','Reveal Effect','Available') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM catalog_weapons n,json_each(n.extras_json) e UNION ALL SELECT 'weapon',id,'payload','system_id','missing_field' FROM catalog_weapons WHERE json_type(shape_json,'$."system_id"') IS NULL UNION ALL SELECT 'weapon',id,'payload','Weapon Name','missing_field' FROM catalog_weapons WHERE json_type(shape_json,'$."Weapon Name"') IS NULL) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_8 AS SELECT * FROM (SELECT 'weapon',id,'payload','system_id','id_mismatch' FROM catalog_weapons WHERE source_id IS NOT NULL AND source_id<>id UNION ALL SELECT 'beliefs' AS entity,n.id,'payload' AS scope,e.key AS field,CASE WHEN e.key IN('system_id','Name','Title','Quote','Desc','Enable','Belief Effect 1','Belief Effect 2') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM catalog_beliefs n,json_each(n.extras_json) e UNION ALL SELECT 'beliefs',id,'payload','system_id','missing_field' FROM catalog_beliefs WHERE json_type(shape_json,'$."system_id"') IS NULL UNION ALL SELECT 'beliefs',id,'payload','Name','missing_field' FROM catalog_beliefs WHERE json_type(shape_json,'$."Name"') IS NULL) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_9 AS SELECT * FROM (SELECT 'beliefs',id,'payload','system_id','id_mismatch' FROM catalog_beliefs WHERE source_id IS NOT NULL AND source_id<>id UNION ALL SELECT 'background' AS entity,n.id,'payload' AS scope,e.key AS field,CASE WHEN e.key IN('system_id','Name','Main Branch','Personality','Desc','Skill 1','Skill 2') THEN 'unexpected_shape' ELSE 'unknown_field' END AS reason FROM catalog_backgrounds n,json_each(n.extras_json) e UNION ALL SELECT 'background',id,'payload','system_id','missing_field' FROM catalog_backgrounds WHERE json_type(shape_json,'$."system_id"') IS NULL UNION ALL SELECT 'background',id,'payload','Name','missing_field' FROM catalog_backgrounds WHERE json_type(shape_json,'$."Name"') IS NULL) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_10 AS SELECT * FROM (SELECT 'background',id,'payload','system_id','id_mismatch' FROM catalog_backgrounds WHERE source_id IS NOT NULL AND source_id<>id UNION ALL SELECT source_kind,source_id,'reference',field,'unresolved_reference' FROM normalization_references r WHERE target_id IS NOT NULL AND target_id<>'' AND NOT EXISTS(SELECT 1 FROM definitions d WHERE d.kind=r.target_kind AND d.id=r.target_id) UNION ALL SELECT kind,id,'payload','kind','unknown_kind' FROM definitions WHERE kind NOT IN('class','school','spell','weapon','beliefs','background') UNION ALL SELECT 'character',p.id,'sheet','Campaign','id_mismatch' FROM character_profiles p JOIN characters c ON c.id=p.id WHERE p.source_campaign IS NOT NULL AND p.source_campaign<>c.campaign_id) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_0_part_11 AS SELECT * FROM (SELECT 'character',character_id,'state','wounds','unexpected_shape' FROM character_wounds WHERE value_type NOT IN('integer','real') UNION ALL SELECT 'class',class_id,'payload','Level '||level||' Perk','unexpected_shape' FROM class_perks WHERE value_type IN('object','array') UNION ALL SELECT 'character',character_id,'reference','character_spells','orphan_character_link' FROM character_spells l WHERE NOT EXISTS(SELECT 1 FROM characters c WHERE c.id=l.character_id) UNION ALL SELECT 'character',character_id,'reference','character_weapons','orphan_character_link' FROM character_weapons l WHERE NOT EXISTS(SELECT 1 FROM characters c WHERE c.id=l.character_id)) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_1_part_1 AS SELECT * FROM (SELECT * FROM normalization_issues_level_0_part_1 UNION ALL SELECT * FROM normalization_issues_level_0_part_2 UNION ALL SELECT * FROM normalization_issues_level_0_part_3 UNION ALL SELECT * FROM normalization_issues_level_0_part_4) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_1_part_2 AS SELECT * FROM (SELECT * FROM normalization_issues_level_0_part_5 UNION ALL SELECT * FROM normalization_issues_level_0_part_6 UNION ALL SELECT * FROM normalization_issues_level_0_part_7 UNION ALL SELECT * FROM normalization_issues_level_0_part_8) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues_level_1_part_3 AS SELECT * FROM (SELECT * FROM normalization_issues_level_0_part_9 UNION ALL SELECT * FROM normalization_issues_level_0_part_10 UNION ALL SELECT * FROM normalization_issues_level_0_part_11) LIMIT -1 OFFSET 0;

CREATE VIEW normalization_issues AS SELECT * FROM (SELECT * FROM normalization_issues_level_1_part_1 UNION ALL SELECT * FROM normalization_issues_level_1_part_2 UNION ALL SELECT * FROM normalization_issues_level_1_part_3) LIMIT -1 OFFSET 0;

DELETE FROM normalization_checks;
